import numpy as np
import time
from scipy.signal import fftconvolve


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = fftconvolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    num = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return -1.0
    return num / den


def construct(budget_seconds, start):
    t0 = time.process_time()
    N = 10000
    x = 2.0 * np.arange(N) / (N - 1) - 1.0

    best_h = None
    best_r = -1.0

    # power profiles (1-|x|^p)^q
    for p in (1, 2, 3):
        base = np.clip(1.0 - np.abs(x) ** p, 0.0, None)
        for q in (1, 2, 3):
            h = base ** q
            if time.process_time() - t0 > budget_seconds * 0.8:
                break
            r = _R(h)
            if r > best_r:
                best_r = r
                best_h = h

    # cosine profiles cos(pi x /2)^p
    c = np.cos(np.pi * x / 2.0)
    c = np.clip(c, 0.0, None)
    for p in (1, 2, 3):
        if time.process_time() - t0 > budget_seconds * 0.9:
            break
        h = c ** p
        r = _R(h)
        if r > best_r:
            best_r = r
            best_h = h

    if best_h is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    # Compare with start if provided
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            rs = _R(s)
            if rs > best_r:
                return s

    print("best R =", best_r)
    return best_h

import numpy as np
import time

def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    m = L.max()
    if m <= 0:
        return -1.0
    Lz = np.empty(L.size + 2)
    Lz[0] = 0.0; Lz[-1] = 0.0; Lz[1:-1] = L
    a = Lz[:-1]; b = Lz[1:]
    q = np.sum(a*a + a*b + b*b) / 3.0
    return q / (s * s * m)

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.5

    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            s = np.clip(s, 0, None)
            r = _R(s)
            if r > bestR:
                bestR = r
                best = s.copy()

    # Try candidates
    cands = []
    if best is not None:
        cands.append(best.copy())
    for N in (100, 200, 500):
        x = np.linspace(0, np.pi, N)
        cands.append(np.sin(x)**2 + 1e-3)
    for c in cands:
        if time.process_time() - t0 > deadline:
            break
        c = np.asarray(c, dtype=float); c = c / c.sum()
        r = _R(c)
        if r > bestR:
            bestR = r; best = c.copy()

    if best is None:
        best = np.ones(50); bestR = _R(best)

    rng = np.random.RandomState(7)
    cur = best.copy(); curR = bestR

    # Adaptive coordinate descent with growing N; also smoothing moves.
    while True:
        if time.process_time() - t0 > deadline:
            break
        N = cur.size
        # perturb small contiguous block
        trial = cur.copy()
        k = rng.randint(1, max(2, N // 30 + 1))
        start_i = rng.randint(0, N)
        idx = (start_i + np.arange(k)) % N
        trial[idx] *= np.exp(rng.randn(k) * 0.15)
        trial = np.clip(trial, 0, None)
        if trial.sum() <= 0:
            continue
        trial /= trial.sum()
        r = _R(trial)
        if r > curR:
            cur = trial; curR = r
            if r > bestR:
                bestR = r; best = trial.copy()
        else:
            # occasionally accept worse to escape
            if rng.rand() < 0.02:
                cur = trial; curR = r

    # Try increasing N by resampling best (finer discretization often helps)
    if best is not None:
        for factor in (2, 3, 4, 5, 8):
            if time.process_time() - t0 > deadline:
                break
            Nnew = min(50000, best.size * factor)
            if Nnew == best.size:
                continue
            idx = np.linspace(0, best.size - 1, Nnew)
            trial = np.interp(idx, np.arange(best.size), best)
            trial = np.clip(trial, 0, None)
            if trial.sum() <= 0:
                continue
            r = _R(trial)
            if r > bestR:
                bestR = r; best = trial.copy()

        # refine at best N
        cur = best.copy(); curR = bestR
        while True:
            if time.process_time() - t0 > deadline:
                break
            N = cur.size
            trial = cur.copy()
            k = rng.randint(1, max(2, N // 50 + 1))
            start_i = rng.randint(0, N)
            idx = (start_i + np.arange(k)) % N
            trial[idx] *= np.exp(rng.randn(k) * 0.08)
            trial = np.clip(trial, 0, None)
            if trial.sum() <= 0:
                continue
            trial /= trial.sum()
            r = _R(trial)
            if r > curR:
                cur = trial; curR = r
                if r > bestR:
                    bestR = r; best = trial.copy()

    if best is None:
        best = np.ones(50)
    best = np.clip(best, 0, None)
    if best.sum() <= 0:
        best = np.ones(50)
    return best

