import time
import numpy as np
from scipy.signal import fftconvolve
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    L = fftconvolve(h, h, mode='full')
    g = np.concatenate(([0.0], L, [0.0]))
    Q = np.sum(g[:-1] ** 2 + g[:-1] * g[1:] + g[1:] ** 2) / 3.0
    S = np.sum(h)
    M = np.max(g)
    if S <= 0 or M <= 0:
        return 0.0
    return Q / (S * S * M)


def _Rg(h):
    N = h.size
    L = fftconvolve(h, h, mode='full')
    g = np.concatenate(([0.0], L, [0.0]))
    Q = np.sum(g[:-1] ** 2 + g[:-1] * g[1:] + g[1:] ** 2) / 3.0
    S = np.sum(h)
    j = int(np.argmax(g))
    M = g[j]
    if S <= 0 or M <= 0 or Q <= 0:
        return 0.0, np.zeros(N)
    dQdg = (4.0 * g + np.concatenate(([0.0], g[:-1])) + np.concatenate((g[1:], [0.0]))) / 3.0
    w = dQdg[1:2 * N]
    conv = fftconvolve(w, h[::-1], mode='full')
    dQdh = 2.0 * conv[N - 1:2 * N - 1]
    dMdh = np.zeros(N)
    k = j - 1
    if 0 <= k <= 2 * N - 2:
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        dMdh[lo:hi + 1] = 2.0 * h[k - hi:k - lo + 1][::-1]
    grad = dQdh / Q - 2.0 / S - dMdh / M
    return Q / (S * S * M), grad


def _Rg_soft(h, beta):
    N = h.size
    L = fftconvolve(h, h, mode='full')
    g = np.concatenate(([0.0], L, [0.0]))
    Q = np.sum(g[:-1] ** 2 + g[:-1] * g[1:] + g[1:] ** 2) / 3.0
    S = np.sum(h)
    gmax = np.max(g)
    e = np.exp(beta * (g - gmax))
    Z = np.sum(e)
    if Z <= 0 or not np.isfinite(Z):
        return _Rg(h)
    wts = e / Z
    Mbeta = (1.0 / beta) * np.log(Z) + gmax
    if S <= 0 or Mbeta <= 0 or Q <= 0:
        return 0.0, np.zeros(N)
    dQdg = (4.0 * g + np.concatenate(([0.0], g[:-1])) + np.concatenate((g[1:], [0.0]))) / 3.0
    wq = dQdg[1:2 * N]
    convQ = fftconvolve(wq, h[::-1], mode='full')
    dQdh = 2.0 * convQ[N - 1:2 * N - 1]
    wm = wts[1:2 * N]
    convM = fftconvolve(wm, h[::-1], mode='full')
    dMdh = 2.0 * convM[N - 1:2 * N - 1]
    grad = dQdh / Q - 2.0 / S - dMdh / Mbeta
    return Q / (S * S * Mbeta), grad


def _lbfgs(h, deadline, maxiter=300):
    if time.process_time() > deadline:
        return h, _R(h)
    x0 = np.maximum(h, 0.0).copy()
    if x0.sum() <= 0:
        return h, _R(h)

    def f(x):
        R, g = _Rg(x)
        return -R, -g

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * x0.size,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter + 10,
                                'ftol': 1e-15, 'gtol': 1e-14})
        xr = np.maximum(res.x, 0.0)
        if xr.sum() > 0:
            Rr = _R(xr)
            if Rr > _R(h):
                return xr, Rr
    except Exception:
        pass
    return h, _R(h)


def _lbfgs_soft(h, beta, deadline, maxiter=200):
    if time.process_time() > deadline:
        return h, _R(h)
    x0 = np.maximum(h, 0.0).copy()
    if x0.sum() <= 0:
        return h, _R(h)

    def f(x):
        R, g = _Rg_soft(x, beta)
        return -R, -g

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * x0.size,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter + 10,
                                'ftol': 1e-15, 'gtol': 1e-14})
        xr = np.maximum(res.x, 0.0)
        if xr.sum() > 0:
            Rr = _R(xr)
            if Rr > _R(h):
                return xr, Rr
    except Exception:
        pass
    return h, _R(h)


def _upsample(h, N):
    xp = np.linspace(0.0, 1.0, h.size)
    x = np.linspace(0.0, 1.0, N)
    out = np.interp(x, xp, h)
    out = np.maximum(out, 0.0)
    s = out.sum()
    if s > 0:
        out /= s
    else:
        out = np.ones(N)
        out /= N
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    best_h = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            s = np.maximum(s, 0.0)
            s = s / s.sum()
            best_h = s.copy()
            best_R = _R(s)

    if best_h is None:
        N = 8000
        x = np.linspace(-1, 1, N)
        best_h = np.maximum(np.cos(0.5 * np.pi * x), 0.0) + 0.01
        best_h /= best_h.sum()
        best_R = _R(best_h)

    N = best_h.size

    # Stage 1: hard L-BFGS on current resolution
    h, R = _lbfgs(best_h, t0 + budget_seconds * 0.30, maxiter=200)
    if R > best_R:
        best_R, best_h = R, h

    # Stage 2: soft-max smoothing to escape the flat max plateau
    for beta in (20000.0, 5000.0, 1500.0, 500.0, 150.0):
        if time.process_time() > t0 + budget_seconds * 0.62:
            break
        h, R = _lbfgs_soft(best_h, beta, t0 + budget_seconds * 0.62, maxiter=120)
        if R > best_R:
            best_R, best_h = R, h

    # Stage 3: upsample and refine at higher resolution
    targets = [N, 12000, 16000, 20000, 24000]
    seen = set()
    for Nt in targets:
        if Nt in seen or Nt < N:
            continue
        seen.add(Nt)
        if time.process_time() > t0 + budget_seconds * 0.93:
            break
        hu = _upsample(best_h, Nt)
        frac = 0.93 - (time.process_time() - t0) / budget_seconds
        dl = t0 + budget_seconds * (0.93 - 0.05 * (1 - frac))
