import time
import numpy as np
from scipy.signal import fftconvolve
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    L = fftconvolve(h, h, mode='full')
    g = np.concatenate(([0.0], L, [0.0]))
    Q = np.sum(g[:-1] ** 2 + g[:-1] * g[1:] + g[1:] ** 2) / 3.0
    S = np.sum(h)
    M = np.max(g)
    if S <= 0 or M <= 0:
        return 0.0
    return Q / (S * S * M)


def _Rg(h):
    N = h.size
    L = fftconvolve(h, h, mode='full')
    g = np.concatenate(([0.0], L, [0.0]))
    Q = np.sum(g[:-1] ** 2 + g[:-1] * g[1:] + g[1:] ** 2) / 3.0
    S = np.sum(h)
    j = int(np.argmax(g))
    M = g[j]
    if S <= 0 or M <= 0 or Q <= 0:
        return 0.0, np.zeros(N)
    dQdg = (4.0 * g + np.concatenate(([0.0], g[:-1])) + np.concatenate((g[1:], [0.0]))) / 3.0
    w = dQdg[1:2 * N]
    conv = fftconvolve(w, h[::-1], mode='full')
    dQdh = 2.0 * conv[N - 1:2 * N - 1]
    dMdh = np.zeros(N)
    k = j - 1
    if 0 <= k <= 2 * N - 2:
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        dMdh[lo:hi + 1] = 2.0 * h[k - hi:k - lo + 1][::-1]
    grad = dQdh / Q - 2.0 / S - dMdh / M
    return Q / (S * S * M), grad


def _Rg_p(h, p):
    """Lp-norm smoothed max: M_p = (sum g^p)^(1/p)."""
    N = h.size
    L = fftconvolve(h, h, mode='full')
    g = np.concatenate(([0.0], L, [0.0]))
    Q = np.sum(g[:-1] ** 2 + g[:-1] * g[1:] + g[1:] ** 2) / 3.0
    S = np.sum(h)
    if S <= 0 or Q <= 0:
        return 0.0, np.zeros(N)
    gp = np.maximum(g, 0.0) ** p
    sp = np.sum(gp)
    if sp <= 0 or not np.isfinite(sp):
        return _Rg(h)
    Mp = sp ** (1.0 / p)
    if Mp <= 0 or not np.isfinite(Mp):
        return _Rg(h)
    dMdgp = np.maximum(g, 0.0) ** (p - 1.0) * (Mp ** (1.0 - p))
    dQdg = (4.0 * g + np.concatenate(([0.0], g[:-1])) + np.concatenate((g[1:], [0.0]))) / 3.0
    wq = dQdg[1:2 * N]
    convQ = fftconvolve(wq, h[::-1], mode='full')
    dQdh = 2.0 * convQ[N - 1:2 * N - 1]
    wm = dMdgp[1:2 * N]
    convM = fftconvolve(wm, h[::-1], mode='full')
    dMdh = 2.0 * convM[N - 1:2 * N - 1]
    grad = dQdh / Q - 2.0 / S - dMdh / Mp
    return Q / (S * S * Mp), grad


def _upsample(h, N):
    xp = np.linspace(0.0, 1.0, h.size)
    x = np.linspace(0.0, 1.0, N)
    out = np.interp(x, xp, h)
    out = np.maximum(out, 0.0)
    s = out.sum()
    if s > 0:
        out /= s
    else:
        out = np.ones(N)
        out /= N
    return out


def _lbfgs(h, deadline, maxiter=200):
    if time.process_time() > deadline:
        return h, _R(h)
    x0 = np.maximum(h, 0.0).copy()
    if x0.sum() <= 0:
        return h, _R(h)

    def f(x):
        R, g = _Rg(x)
        return -R, -g

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * x0.size,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter + 10,
                                'ftol': 1e-15, 'gtol': 1e-14})
        xr = np.maximum(res.x, 0.0)
        if xr.sum() > 0:
            Rr = _R(xr)
            if Rr > _R(h):
                return xr, Rr
    except Exception:
        pass
    return h, _R(h)


def _lbfgs_p(h, p, deadline, maxiter=200):
    if time.process_time() > deadline:
        return h, _R(h)
    x0 = np.maximum(h, 0.0).copy()
    if x0.sum() <= 0:
        return h, _R(h)

    def f(x):
        R, g = _Rg_p(x, p)
        return -R, -g

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * x0.size,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter + 10,
                                'ftol': 1e-15, 'gtol': 1e-14})
        xr = np.maximum(res.x, 0.0)
        if xr.sum() > 0:
            Rr = _R(xr)
            if Rr > _R(h):
                return xr, Rr
    except Exception:
        pass
    return h, _R(h)


def _adam_p(h, p, iters, deadline, lr0=1e-3):
    N = h.size
    beta1, beta2, eps = 0.9, 0.999, 1e-8
    m = np.zeros(N)
    v = np.zeros(N)
    best_h = h.copy()
    best_R = _R(h)
    for it in range(1, iters + 1):
        if time.process_time() > deadline:
            break
        Rp, grad = _Rg_p(h, p)
        if Rp <= 0 or not np.all(np.isfinite(grad)):
            break
        m = beta1 * m + (1 - beta1) * grad
        v = beta2 * v + (1 - beta2) * grad * grad
        mhat = m / (1 - beta1 ** it)
        vhat = v / (1 - beta2 ** it)
        lr = lr0 / (1.0 + it / 2000.0)
        h = h + lr * mhat / (np.sqrt(vhat) + eps)
        h = np.maximum(h, 0.0)
        if h.sum() <= 0:
            break
        R = _R(h)
        if R > best_R:
            best_R = R
            best_h = h.copy()
    return best_h, best_R


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds
    hard_deadline = t0 + budget * 0.95

    fallback_h = None
    fallback_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            s = np.maximum(s, 0.0)
            s = s / s.sum()
            fallback_h = s.copy()
            fallback_R = _R(s)

    if fallback_h is None:
        h = np.ones(1000)
        return h / h.sum()

    best_h = fallback_h.copy()
    best_R = fallback_R

    # Upsample start to a higher resolution to escape the discrete grain.
    N_hi = 4800
    h_hi = _upsample(fallback_h, N_hi)
    R_hi = _R(h_hi)

    # Water-filling: Lp annealing with Adam, then exact L-BFGS polish.
    ps = (4, 8, 16, 32, 64, 128, 256, 512, 1024, 2048)
    lp_start = time.process_time()
    lp_end = t0 + budget * 0.80
    n = len(ps)
    for idx, p in enumerate(ps):
        if time.process_time() > lp_end:
            break
        frac = (idx + 1) / n
        stage_deadline = lp_start + (lp_end - lp_start) * frac
        h = best_h if False else h_hi
        h, _ = _adam_p(h, p, 2500, stage_deadline, lr0=1.2e-3)
        Rt = _R(h)
        if Rt > R_hi:
            R_hi = Rt
            h_hi = h.copy()
        # Short exact polish between stages keeps the peak sharp.
        if time.process_time() < stage_deadline:
            h2, R2 = _lbfgs(h_hi, stage_deadline, maxiter=120)
            if R2 > R_hi:
                h_hi, R_hi = h2, R2

    if R_hi > best_R:
        best_h, best_R = h_hi, R_hi

    # Final aggressive exact polish on the winner.
    if time.process_time() < hard_deadline:
        h2, R2 = _lbfgs(best_h, hard_deadline, maxiter=1000)
        if R2 > best_R:
            best_h, best_R = h2, R2
    if time.process_time() < hard_deadline:
        h2, R2 = _lbfgs_p(best_h, 512, hard_deadline, maxiter=800)
        if R2 > best_R:
            best_h, best_R = h2, R2
    if time.process_time() < hard_deadline:
        h2, R2 = _lbfgs(best_h, hard_deadline, maxiter=1000)
        if R2 > best_R:
            best_h, best_R = h2, R2

    if fallback_R > best_R:
        best_h, best_R = fallback_h, fallback_R

    best_h = np.maximum(best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(best_h.size)
    if best_h.size > 50000:
        best_h = _upsample(best_h, 50000)
    return best_h

