    for it in range(1, iters + 1):
        if time.process_time() > deadline:
            break
        Rp, grad = _Rg_lse(h, tau)
        if Rp <= 0 or not np.all(np.isfinite(grad)):
            break
        m = beta1 * m + (1 - beta1) * grad
        v = beta2 * v + (1 - beta2) * grad * grad
        mhat = m / (1 - beta1 ** it)
        vhat = v / (1 - beta2 ** it)
        lr = lr0 / (1.0 + it / 2000.0)
        h = h + lr * mhat / (np.sqrt(vhat) + eps)
        h = np.maximum(h, 0.0)
        if h.sum() <= 0:
            break
        R = _R(h)
        if R > best_R:
            best_R = R
            best_h = h.copy()
    return best_h, best_R


def _param_search(N, deadline):
    """Search parametric families for a good starting shape at resolution N."""
    x = np.linspace(0.0, 1.0, N)
    u = np.abs(2.0 * x - 1.0)  # 0 at center, 1 at edges
    best_h = None
    best_R = -1.0

    def try_h(h):
        nonlocal best_h, best_R
        h = np.maximum(h, 0.0)
        s = h.sum()
        if s <= 0:
            return
        h = h / s
        R = _R(h)
        if R > best_R:
            best_R = R
            best_h = h.copy()

    # Family 1: (1 - |2x-1|^p)^q  -- U-shaped for small p, bump for large p
    def f1(pq):
        p, q = pq
        base = np.maximum(1.0 - u ** p, 0.0)
        return base ** q

    # Family 2: exp(-a |2x-1|^p)
    def f2(ap):
        a, p = ap
        return np.exp(-a * u ** p)

    # Family 3: 1 + A cos(pi x)
    def f3(A):
        return 1.0 + A[0] * np.cos(np.pi * x)

    try:
        if time.process_time() < deadline:
            res = differential_evolution(
                lambda pq: -_R(f1(pq) / max(f1(pq).sum(), 1e-300)),
                bounds=[(0.1, 10.0), (0.1, 10.0)],
                maxiter=20, popsize=10, tol=1e-8, seed=1,
                polish=False, init='sobol')
            try_h(f1(res.x))
    except Exception:
        pass

    try:
        if time.process_time() < deadline:
            res = differential_evolution(
                lambda ap: -_R(f2(ap) / max(f2(ap).sum(), 1e-300)),
                bounds=[(0.0, 10.0), (0.1, 10.0)],
                maxiter=20, popsize=10, tol=1e-8, seed=2,
                polish=False, init='sobol')
            try_h(f2(res.x))
    except Exception:
        pass

    try:
        if time.process_time() < deadline:
            res = differential_evolution(
                lambda A: -_R(f3(A) / max(f3(A).sum(), 1e-300)),
                bounds=[(-0.99, 10.0)],
                maxiter=20, popsize=10, tol=1e-8, seed=3,
                polish=False, init='sobol')
            try_h(f3(res.x))
    except Exception:
        pass

    # Also try a few hand-picked U-shapes
    for p in (0.3, 0.5, 0.7, 1.0, 1.5):
        for q in (0.5, 1.0, 2.0):
            try_h(f1((p, q)))

    return best_h, best_R


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds
    hard_deadline = t0 + budget * 0.95

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            s = np.maximum(s, 0.0)
            s = s / s.sum()
            best_h = s.copy()
            best_R = _R(s)
        else:
            best_h = None
    else:
        best_h = None

    if best_h is None:
        h = np.ones(1000)
        return h / h.sum()

    # Parametric search at low resolution.
    param_end = t0 + budget * 0.35
    try:
        ph, pR = _param_search(2000, param_end)
    except Exception:
        ph, pR = None, -1.0

    if ph is not None and pR > best_R:
        # Upsample parametric candidate to N=16000 and refine.
        cand = _upsample(ph, 16000)
        cand_R = _R(cand)
        if cand_R > best_R:
            best_h, best_R = cand, cand_R

    # LSE annealing: tau from 0.05*M to 1e-4*M over 8 stages.
    lse_end = t0 + budget * 0.70
    ps = np.geomspace(0.05, 1e-4, 8)
    h = best_h.copy()
    R = best_R
    M0 = np.max(np.concatenate(([0.0], fftconvolve(h, h, mode='full'), [0.0])))
    if M0 <= 0:
        M0 = 1.0
    n = len(ps)
    for idx, frac in enumerate(ps):
        if time.process_time() > lse_end:
            break
        tau = frac * M0
        stage_deadline = t0 + (lse_end - t0) * (idx + 1) / n
        h2, R2 = _adam_lse(h, tau, 200, stage_deadline, lr0=1e-3)
        if R2 > R:
            h, R = h2, R2
    if R > best_R:
        best_h, best_R = h, R

    # Exact L-BFGS polish.
    if time.process_time() < hard_deadline:
        h3, R3 = _lbfgs(best_h, hard_deadline, maxiter=200)
        if R3 > best_R:
            best_h, best_R = h3, R3

    best_h = np.maximum(best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(best_h.size)
    if best_h.size > 50000:
        best_h = _upsample(best_h, 50000)
    return best_h

import time
import numpy as np
from scipy.signal import fftconvolve
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    L = fftconvolve(h, h, mode='full')
    g = np.concatenate(([0.0], L, [0.0]))
    Q = np.sum(g[:-1] ** 2 + g[:-1] * g[1:] + g[1:] ** 2) / 3.0
    S = np.sum(h)
    M = np.max(g)
    if S <= 0 or M <= 0:
        return 0.0
    return Q / (S * S * M)


def _Rg(h):
    N = h.size
    L = fftconvolve(h, h, mode='full')
    g = np.concatenate(([0.0], L, [0.0]))
    Q = np.sum(g[:-1] ** 2 + g[:-1] * g[1:] + g[1:] ** 2) / 3.0
    S = np.sum(h)
    j = int(np.argmax(g))
    M = g[j]
    if S <= 0 or M <= 0 or Q <= 0:
        return 0.0, np.zeros(N)
    dQdg = (4.0 * g + np.concatenate(([0.0], g[:-1])) + np.concatenate((g[1:], [0.0]))) / 3.0
    w = dQdg[1:2 * N]
    conv = fftconvolve(w, h[::-1], mode='full')
    dQdh = 2.0 * conv[N - 1:2 * N - 1]
    dMdh = np.zeros(N)
    k = j - 1
    if 0 <= k <= 2 * N - 2:
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        dMdh[lo:hi + 1] = 2.0 * h[k - hi:k - lo + 1][::-1]
    grad = dQdh / Q - 2.0 / S - dMdh / M
    return Q / (S * S * M), grad


def _upsample(h, N):
    xp = np.linspace(0.0, 1.0, h.size)
    x = np.linspace(0.0, 1.0, N)
    out = np.interp(x, xp, h)
    out = np.maximum(out, 0.0)
    s = out.sum()
    if s > 0:
        out /= s
    else:
        out = np.ones(N)
        out /= N
    return out


def _downsample_block(h, N):
    n = h.size
    if n == N:
        return h.copy()
    edges = np.linspace(0, n, N + 1)
    out = np.empty(N)
    for i in range(N):
        a = int(round(edges[i]))
        b = int(round(edges[i + 1]))
        if b <= a:
            b = min(a + 1, n)
        out[i] = h[a:b].mean()
    out = np.maximum(out, 0.0)
    s = out.sum()
    if s > 0:
        out /= s
    return out


def _lbfgs(h, deadline, maxiter=200):
    if time.process_time() > deadline:
        return h, _R(h)
    x0 = np.maximum(h, 0.0).copy()
    if x0.sum() <= 0:
        return h, _R(h)

    def f(x):
        R, g = _Rg(x)
        return -R, -g

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * x0.size,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter + 10,
                                'ftol': 1e-15, 'gtol': 1e-14})
        xr = np.maximum(res.x, 0.0)
        if xr.sum() > 0:
            Rr = _R(xr)
            if Rr > _R(h):
                return xr, Rr
    except Exception:
        pass
    return h, _R(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds
    hard_deadline = t0 + budget * 0.95

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            s = np.maximum(s, 0.0)
            s = s / s.sum()
            best_h = s.copy()
            best_R = _R(s)
        else:
            best_h = None
    else:
        best_h = None

    if best_h is None:
        h = np.ones(1000)
        return h / h.sum()

    # Coarse multi-start experiment.
    coarse_end = t0 + budget * 0.55
    Nc = 1000
    hc = _downsample_block(best_h, Nc)
    rng = np.random.default_rng(12345)
    ncopies = 5
    best_coarse = hc.copy()
    best_coarse_R = _R(hc)
    for k in range(ncopies):
        if time.process_time() > coarse_end:
            break
        if k == 0:
            cand = hc.copy()
        else:
            noise = rng.normal(0.0, 0.15, size=Nc)
            cand = hc * np.exp(noise)
            cand = np.maximum(cand, 0.0)
            sc = cand.sum()
            if sc > 0:
                cand /= sc
            else:
                continue
        stage_deadline = t0 + (coarse_end - t0) * (k + 1) / ncopies
        cand2, Rc = _lbfgs(cand, stage_deadline, maxiter=150)
        if Rc > best_coarse_R:
            best_coarse_R = Rc
            best_coarse = cand2

    # Upsample coarse best to 16000 and polish.
    Nf = 16000
    hf = _upsample(best_coarse, Nf)
    Rf = _R(hf)
    if time.process_time() < hard_deadline:
        hf2, Rf2 = _lbfgs(hf, hard_deadline, maxiter=400)
        if Rf2 > Rf:
            hf, Rf = hf2, Rf2

    if Rf > best_R:
        best_h, best_R = hf, Rf

    best_h = np.maximum(best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(best_h.size)
    if best_h.size > 50000:
        best_h = _upsample(best_h, 50000)
    return best_h

import time
import numpy as np
from scipy.signal import fftconvolve
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    L = fftconvolve(h, h, mode='full')
    g = np.concatenate(([0.0], L, [0.0]))
    Q = np.sum(g[:-1] ** 2 + g[:-1] * g[1:] + g[1:] ** 2) / 3.0
    S = np.sum(h)
    M = np.max(g)
    if S <= 0 or M <= 0:
        return 0.0
    return Q / (S * S * M)


def _Rg(h):
    N = h.size
    L = fftconvolve(h, h, mode='full')
    g = np.concatenate(([0.0], L, [0.0]))
    Q = np.sum(g[:-1] ** 2 + g[:-1] * g[1:] + g[1:] ** 2) / 3.0
    S = np.sum(h)
    j = int(np.argmax(g))
    M = g[j]
    if S <= 0 or M <= 0 or Q <= 0:
        return 0.0, np.zeros(N)
    dQdg = (4.0 * g + np.concatenate(([0.0], g[:-1])) + np.concatenate((g[1:], [0.0]))) / 3.0
    w = dQdg[1:2 * N]
    conv = fftconvolve(w, h[::-1], mode='full')
    dQdh = 2.0 * conv[N - 1:2 * N - 1]
    dMdh = np.zeros(N)
    k = j - 1
    if 0 <= k <= 2 * N - 2:
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        dMdh[lo:hi + 1] = 2.0 * h[k - hi:k - lo + 1][::-1]
    grad = dQdh / Q - 2.0 / S - dMdh / M
    return Q / (S * S * M), grad


def _Rg_lse(h, tau):
    N = h.size
    L = fftconvolve(h, h, mode='full')
    g = np.concatenate(([0.0], L, [0.0]))
    Q = np.sum(g[:-1] ** 2 + g[:-1] * g[1:] + g[1:] ** 2) / 3.0
    S = np.sum(h)
    if S <= 0 or Q <= 0:
        return 0.0, np.zeros(N)
    gmax = np.max(g)
    if gmax <= 0:
        return _Rg(h)
    z = (g - gmax) / tau
    zmax = np.max(z)
    e = np.exp(z - zmax)
    se = np.sum(e)
    if se <= 0 or not np.isfinite(se):
        return _Rg(h)
    M = tau * (np.log(se) + zmax) + gmax
    if M <= 0 or not np.isfinite(M):
        return _Rg(h)
    dMdg = e / se
    dQdg = (4.0 * g + np.concatenate(([0.0], g[:-1])) + np.concatenate((g[1:], [0.0]))) / 3.0
    wq = dQdg[1:2 * N]
    convQ = fftconvolve(wq, h[::-1], mode='full')
    dQdh = 2.0 * convQ[N - 1:2 * N - 1]
    wm = dMdg[1:2 * N]
    convM = fftconvolve(wm, h[::-1], mode='full')
    dMdh = 2.0 * convM[N - 1:2 * N - 1]
    grad = dQdh / Q - 2.0 / S - dMdh / M
    return Q / (S * S * M), grad


def _upsample(h, N):
    xp = np.linspace(0.0, 1.0, h.size)
    x = np.linspace(0.0, 1.0, N)
    out = np.interp(x, xp, h)
    out = np.maximum(out, 0.0)
    s = out.sum()
    if s > 0:
        out /= s
    else:
        out = np.ones(N)
        out /= N
    return out


def _lbfgs(h, deadline, maxiter=200):
    if time.process_time() > deadline:
        return h, _R(h)
    x0 = np.maximum(h, 0.0).copy()
    if x0.sum() <= 0:
        return h, _R(h)

    def f(x):
        R, g = _Rg(x)
        return -R, -g

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * x0.size,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter + 10,
                                'ftol': 1e-15, 'gtol': 1e-14})
        xr = np.maximum(res.x, 0.0)
        if xr.sum() > 0:
            Rr = _R(xr)
            if Rr > _R(h):
                return xr, Rr
    except Exception:
        pass
    return h, _R(h)


def _adam_lse(h, tau, iters, deadline, lr0=1e-3):
    N = h.size
    beta1, beta2, eps = 0.9, 0.999, 1e-8
    m = np.zeros(N)
    v = np.zeros(N)
    best_h = h.copy()
    best_R = _R(h)
    for it in range(1, iters + 1):
        if time.process_time() > deadline:
            break
        Rp, grad = _Rg_lse(h, tau)
        if Rp <= 0 or not np.all(np.isfinite(grad)):
            break
        m = beta1 * m + (1 - beta1) * grad
        v = beta2 * v + (1 - beta2) * grad * grad
        mhat = m / (1 - beta1 ** it)
        vhat = v / (1 - beta2 ** it)
        lr = lr0 / (1.0 + it / 2000.0)
        h = h + lr * mhat / (np.sqrt(vhat) + eps)
        h = np.maximum(h, 0.0)
        if h.sum() <= 0:
            break
        R = _R(h)
        if R > best_R:
            best_R = R
            best_h = h.copy()
    return best_h, best_R


def _expand_blocks(bh, edges, N):
    # edges: length nb+1 boundaries in [0, N]; bh: length nb block heights
    out = np.empty(N)
    for i in range(bh.size):
        lo = edges[i]
        hi = edges[i + 1]
        if hi > lo:
            out[lo:hi] = bh[i]
    return out


def _block_lbfgs(h, nb, deadline, maxiter=200):
    N = h.size
    if time.process_time() > deadline:
        return h, _R(h)
    h = np.maximum(h, 0.0)
    c = np.cumsum(h)
    total = c[-1]
    if total <= 0:
        return h, _R(h)
    # block boundaries at quantiles of cumulative mass
    qs = np.linspace(0.0, 1.0, nb + 1)
    targets = qs * total
    edges = np.searchsorted(c, targets, side='left')
    edges[0] = 0
    edges[-1] = N
    # ensure strictly increasing
    for i in range(1, nb + 1):
        if edges[i] <= edges[i - 1]:
            edges[i] = edges[i - 1] + 1
    edges = np.minimum(edges, N)
    # fix if overflow
    if edges[-1] > N:
        edges = np.linspace(0, N, nb + 1).astype(int)
    # initial block heights = mean of h within block
    bh = np.empty(nb)
    for i in range(nb):
        lo, hi = edges[i], edges[i + 1]
        if hi > lo:
            bh[i] = np.mean(h[lo:hi])
        else:
            bh[i] = 0.0
    if bh.sum() <= 0:
        return h, _R(h)

    def expand(x):
        return _expand_blocks(x, edges, N)

    def f(x):
        hh = expand(x)
        R, g = _Rg(hh)
        gb = np.empty(nb)
        for i in range(nb):
            lo, hi = edges[i], edges[i + 1]
            if hi > lo:
                gb[i] = np.sum(g[lo:hi])
            else:
                gb[i] = 0.0
        return -R, -gb

    R0 = _R(h)
    try:
        res = minimize(f, bh, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * nb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter + 10,
                                'ftol': 1e-15, 'gtol': 1e-14})
        bh2 = np.maximum(res.x, 0.0)
        if bh2.sum() > 0:
            h2 = expand(bh2)
            R2 = _R(h2)
            if R2 > R0:
                return h2, R2
    except Exception:
        pass
    return h, R0


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds
    hard_deadline = t0 + budget * 0.95

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            s = np.maximum(s, 0.0)
            s = s / s.sum()
            best_h = s.copy()
            best_R = _R(s)
        else:
            best_h = None
    else:
        best_h = None

    if best_h is None:
        h = np.ones(1000)
        return h / h.sum()

    # Phase 1: block optimization on 2000 equal-mass blocks for ~15s.
    block_end = t0 + budget * 0.50
    h = best_h.copy()
    R = best_R
    h2, R2 = _block_lbfgs(h, 2000, block_end, maxiter=300)
    if R2 > R:
        h, R = h2, R2
    if R > best_R:
        best_h, best_R = h, R

    # Phase 2: expand to 16000 steps and polish with exact L-BFGS for ~8s.
    polish_end = t0 + budget * 0.78
    if time.process_time() < polish_end:
        target_N = 16000
        if best_h.size != target_N:
            h3 = _upsample(best_h, target_N)
        else:
            h3 = best_h.copy()
        h4, R4 = _lbfgs(h3, polish_end, maxiter=200)
        if R4 > best_R:
            best_h, best_R = h4, R4

    # Phase 3: if time remains, another exact polish pass.
    if time.process_time() < hard_deadline:
        h5, R5 = _lbfgs(best_h, hard_deadline, maxiter=200)
        if R5 > best_R:
            best_h, best_R = h5, R5

    best_h = np.maximum(best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(best_h.size)
    if best_h.size > 50000:
        best_h = _upsample(best_h, 50000)
    return best_h

