        convM = fftconvolve(wm, h[::-1], mode='full')
        dMdh = 2.0 * convM[N - 1:2 * N - 1]
    elif avg:
        M = gmax
        J = np.where(g >= gmax * (1.0 - 1e-4))[0]
        if J.size == 0:
            J = np.array([int(np.argmax(g))])
        dMdh = np.zeros(N)
        for j in J:
            k = j - 1
            if 0 <= k <= 2 * N - 2:
                lo = max(0, k - N + 1)
                hi = min(N - 1, k)
                dMdh[lo:hi + 1] += 2.0 * h[k - hi:k - lo + 1][::-1]
        dMdh /= J.size
    else:
        M = gmax
        j = int(np.argmax(g))
        dMdh = np.zeros(N)
        k = j - 1
        if 0 <= k <= 2 * N - 2:
            lo = max(0, k - N + 1)
            hi = min(N - 1, k)
            dMdh[lo:hi + 1] = 2.0 * h[k - hi:k - lo + 1][::-1]

    grad = dQdh / Q - 2.0 / S - dMdh / M
    return Q / (S * S * M), grad


def _upsample(h, N):
    xp = np.linspace(0.0, 1.0, h.size)
    x = np.linspace(0.0, 1.0, N)
    out = np.interp(x, xp, h)
    out = np.maximum(out, 0.0)
    s = out.sum()
    if s > 0:
        out /= s
    else:
        out = np.ones(N) / N
    return out


def _lbfgs(h, deadline, maxiter=200, mode='exact'):
    if time.process_time() > deadline:
        return h, _R(h)
    x0 = np.maximum(h, 0.0).copy()
    if x0.sum() <= 0:
        return h, _R(h)

    def f(x):
        if mode == 'avg':
            R, g = _grads(x, avg=True)
        elif mode == 'exact':
            R, g = _grads(x)
        else:
            R, g = _grads(x, tau=mode)
        return -R, -g

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * x0.size,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter + 10,
                                'ftol': 1e-15, 'gtol': 1e-14})
        xr = np.maximum(res.x, 0.0)
        if xr.sum() > 0:
            Rr = _R(xr)
            if Rr > _R(h):
                return xr, Rr
    except Exception:
        pass
    return h, _R(h)


def _adam(h, tau, iters, deadline, lr0=8e-4):
    N = h.size
    beta1, beta2, eps = 0.9, 0.999, 1e-8
    m = np.zeros(N)
    v = np.zeros(N)
    best_h = h.copy()
    best_R = _R(h)
    for it in range(1, iters + 1):
        if time.process_time() > deadline:
            break
        Rp, grad = _grads(h, tau=tau)
        if Rp <= 0 or not np.all(np.isfinite(grad)):
            break
        m = beta1 * m + (1 - beta1) * grad
        v = beta2 * v + (1 - beta2) * grad * grad
        mhat = m / (1 - beta1 ** it)
        vhat = v / (1 - beta2 ** it)
        lr = lr0 / (1.0 + it / 2000.0)
        h = np.maximum(h + lr * mhat / (np.sqrt(vhat) + eps), 0.0)
        if h.sum() <= 0:
            break
        R = _R(h)
        if R > best_R:
            best_R = R
            best_h = h.copy()
    return best_h, best_R


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_deadline = t0 + budget_seconds * 0.93

    if start is None:
        h = np.ones(1000)
        return h / h.sum()

    s = np.asarray(start, dtype=float).ravel()
    if s.size == 0 or not np.all(np.isfinite(s)) or s.sum() <= 0:
        h = np.ones(1000)
        return h / h.sum()
    s = np.maximum(s, 0.0)
    s = s / s.sum()

    best_h = s.copy()
    best_R = _R(s)

    # Phase A: exact-gradient L-BFGS to refine the start directly.
    if time.process_time() < hard_deadline:
        hA, RA = _lbfgs(best_h, min(t0 + budget_seconds * 0.35, hard_deadline), maxiter=250, mode='exact')
        if RA > best_R:
            best_h, best_R = hA, RA

    # Phase B: averaged-gradient L-BFGS (helps when near-max plateau).
    if time.process_time() < hard_deadline:
        hB, RB = _lbfgs(best_h, min(t0 + budget_seconds * 0.55, hard_deadline), maxiter=250, mode='avg')
        if RB > best_R:
            best_h, best_R = hB, RB

    # Phase C: LSE annealing to break through plateau, then exact polish.
    if time.process_time() < hard_deadline:
        M0 = np.max(np.concatenate(([0.0], fftconvolve(best_h, best_h, mode='full'), [0.0])))
        if M0 <= 0:
            M0 = 1.0
        ps = np.geomspace(1e-3, 1e-6, 6)
        n = len(ps)
        lse_end = min(t0 + budget_seconds * 0.80, hard_deadline)
        h = best_h.copy()
        R = best_R
        for idx, frac in enumerate(ps):
            if time.process_time() > lse_end:
                break
            stage_deadline = t0 + (lse_end - t0) * (idx + 1) / n
            h2, R2 = _adam(h, frac * M0, 200, stage_deadline)
            if R2 > R:
                h, R = h2, R2
        if R > best_R:
            best_h, best_R = h, R

    # Phase D: final exact polish.
    if time.process_time() < hard_deadline:
        hF, RF = _lbfgs(best_h, hard_deadline, maxiter=300, mode='exact')
        if RF > best_R:
            best_h, best_R = hF, RF

    best_h = np.maximum(best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(best_h.size)
    if best_h.size > 50000:
        best_h = _upsample(best_h, 50000)
    return best_h

import time
import numpy as np
from scipy.signal import fftconvolve
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    L = fftconvolve(h, h, mode='full')
    g = np.concatenate(([0.0], L, [0.0]))
    Q = np.sum(g[:-1] ** 2 + g[:-1] * g[1:] + g[1:] ** 2) / 3.0
    S = np.sum(h)
    M = np.max(g)
    if S <= 0 or M <= 0:
        return 0.0
    return Q / (S * S * M)


def _Rg(h):
    N = h.size
    L = fftconvolve(h, h, mode='full')
    g = np.concatenate(([0.0], L, [0.0]))
    Q = np.sum(g[:-1] ** 2 + g[:-1] * g[1:] + g[1:] ** 2) / 3.0
    S = np.sum(h)
    j = int(np.argmax(g))
    M = g[j]
    if S <= 0 or M <= 0 or Q <= 0:
        return 0.0, np.zeros(N)
    dQdg = (4.0 * g + np.concatenate(([0.0], g[:-1])) + np.concatenate((g[1:], [0.0]))) / 3.0
    w = dQdg[1:2 * N]
    conv = fftconvolve(w, h[::-1], mode='full')
    dQdh = 2.0 * conv[N - 1:2 * N - 1]
    dMdh = np.zeros(N)
    k = j - 1
    if 0 <= k <= 2 * N - 2:
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        dMdh[lo:hi + 1] = 2.0 * h[k - hi:k - lo + 1][::-1]
    grad = dQdh / Q - 2.0 / S - dMdh / M
    return Q / (S * S * M), grad


def _Rg_avg(h):
    """Like _Rg but averages max-gradient over all near-max knots."""
    N = h.size
    L = fftconvolve(h, h, mode='full')
    g = np.concatenate(([0.0], L, [0.0]))
    Q = np.sum(g[:-1] ** 2 + g[:-1] * g[1:] + g[1:] ** 2) / 3.0
    S = np.sum(h)
    M = np.max(g)
    if S <= 0 or M <= 0 or Q <= 0:
        return 0.0, np.zeros(N)
    dQdg = (4.0 * g + np.concatenate(([0.0], g[:-1])) + np.concatenate((g[1:], [0.0]))) / 3.0
    w = dQdg[1:2 * N]
    conv = fftconvolve(w, h[::-1], mode='full')
    dQdh = 2.0 * conv[N - 1:2 * N - 1]
    J = np.where(g >= M * (1.0 - 1e-4))[0]
    if J.size == 0:
        J = np.array([int(np.argmax(g))])
    dMdh = np.zeros(N)
    for j in J:
        k = j - 1
        if 0 <= k <= 2 * N - 2:
            lo = max(0, k - N + 1)
            hi = min(N - 1, k)
            dMdh[lo:hi + 1] += 2.0 * h[k - hi:k - lo + 1][::-1]
    dMdh /= J.size
    grad = dQdh / Q - 2.0 / S - dMdh / M
    return Q / (S * S * M), grad


def _Rg_lse(h, tau):
    N = h.size
    L = fftconvolve(h, h, mode='full')
    g = np.concatenate(([0.0], L, [0.0]))
    Q = np.sum(g[:-1] ** 2 + g[:-1] * g[1:] + g[1:] ** 2) / 3.0
    S = np.sum(h)
    if S <= 0 or Q <= 0:
        return 0.0, np.zeros(N)
    gmax = np.max(g)
    if gmax <= 0:
        return _Rg(h)
    z = (g - gmax) / tau
    zmax = np.max(z)
    e = np.exp(z - zmax)
    se = np.sum(e)
    if se <= 0 or not np.isfinite(se):
        return _Rg(h)
    M = tau * (np.log(se) + zmax) + gmax
    if M <= 0 or not np.isfinite(M):
        return _Rg(h)
    dMdg = e / se
    dQdg = (4.0 * g + np.concatenate(([0.0], g[:-1])) + np.concatenate((g[1:], [0.0]))) / 3.0
    wq = dQdg[1:2 * N]
    convQ = fftconvolve(wq, h[::-1], mode='full')
    dQdh = 2.0 * convQ[N - 1:2 * N - 1]
    wm = dMdg[1:2 * N]
    convM = fftconvolve(wm, h[::-1], mode='full')
    dMdh = 2.0 * convM[N - 1:2 * N - 1]
    grad = dQdh / Q - 2.0 / S - dMdh / M
    return Q / (S * S * M), grad


def _upsample(h, N):
    xp = np.linspace(0.0, 1.0, h.size)
    x = np.linspace(0.0, 1.0, N)
    out = np.interp(x, xp, h)
    out = np.maximum(out, 0.0)
    s = out.sum()
    if s > 0:
        out /= s
    else:
        out = np.ones(N)
        out /= N
    return out


def _lbfgs(h, deadline, maxiter=200, use_avg=False):
    if time.process_time() > deadline:
        return h, _R(h)
    x0 = np.maximum(h, 0.0).copy()
    if x0.sum() <= 0:
        return h, _R(h)

    def f(x):
        if use_avg:
            R, g = _Rg_avg(x)
        else:
            R, g = _Rg(x)
        return -R, -g

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * x0.size,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter + 10,
                                'ftol': 1e-15, 'gtol': 1e-14})
        xr = np.maximum(res.x, 0.0)
        if xr.sum() > 0:
            Rr = _R(xr)
            if Rr > _R(h):
                return xr, Rr
    except Exception:
        pass
    return h, _R(h)


def _lbfgs_log(h, deadline, maxiter=400):
    """Optimize log-heights with averaged-gradient objective."""
    if time.process_time() > deadline:
        return h, _R(h)
    h = np.maximum(np.asarray(h, dtype=float), 0.0)
    if h.sum() <= 0:
        return h, _R(h)
    floor = 1e-8 * np.max(h)
    x0 = np.log(np.maximum(h, floor))

    def f(x):
        hh = np.exp(x)
        R, g = _Rg_avg(hh)
        return -R, -(hh * g)

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * x0.size,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter + 10,
                                'ftol': 1e-15, 'gtol': 1e-14})
        xr = np.clip(res.x, -30.0, 30.0)
        hr = np.exp(xr)
        if hr.sum() > 0:
            Rr = _R(hr)
            if Rr > _R(h):
                return hr, Rr
    except Exception:
        pass
    return h, _R(h)


def _adam_lse(h, tau, iters, deadline, lr0=1e-3):
    N = h.size
    beta1, beta2, eps = 0.9, 0.999, 1e-8
    m = np.zeros(N)
    v = np.zeros(N)
    best_h = h.copy()
    best_R = _R(h)
    for it in range(1, iters + 1):
